local function apply()
	local sm = ScriptManager and ScriptManager.instance
	if not sm then return end
	local patched, missing, total = 0, 0, 0
	for fullType, name in pairs(T) do
		total = total + 1
		local ok, item = pcall(function() return sm:getItem(fullType) end)
		if ok and item then
			local okSet = pcall(function() item:setDisplayName(name) end)
			if not okSet then
				okSet = pcall(function() item:DoParam("DisplayName = " .. name) end)
			end
			if okSet then patched = patched + 1 end
		else
			missing = missing + 1
		end
	end
	print("[LocalCN] DisplayNameFix: " .. tostring(patched) .. " patched, " .. tostring(missing) ..
		" not found (table " .. tostring(total) .. ")")
	local probe = sm:getItem("Base.3rdGenChevyCKseriesFrontSideWindow2")
	print("[LocalCN] probe Base.3rdGenChevyCKseriesFrontSideWindow2 -> " ..
		tostring(probe and probe.getDisplayName and probe:getDisplayName()))
end

LocalCN_DisplayNameFix.apply = apply
if Events and Events.OnInitGlobalModData then Events.OnInitGlobalModData.Add(apply) end
if Events and Events.OnGameBoot then Events.OnGameBoot.Add(apply) end
apply()
